Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest")

	$$$TRACE("phoneNumber: "_pRequest.phoneNumber) 
	$$$TRACE("Operation Type: "_pRequest.operationType)

	set pResponse=##class(Ens.StringResponse).%New()


	if (pRequest.operationType="carrier"){
		set tSC = ..CallTwilioGetPhoneType(pRequest,.phoneTypeResp)		
	 }else{
		set tSC=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError("Invalid request","request: "_pRequest.operationType)
	 }
	 if $$$ISERR(tSC) {
         do $system.OBJ.DisplayError()
         Quit tSC
     }else{
	     set pResponse.StringValue = phoneTypeResp.StringValue
     }		
    quit tSC
